REFINE_ASPECT_ALIASES = {
    "自然支持": ("自然支持",),
    "科技／輔具／工具": ("科技／輔具／工具", "科技/輔具/工具", "科技", "輔具", "工具"),
    "教育（新技能）": ("教育（新技能）", "教育(新技能)", "教育", "新技能"),
    "增強／獎勵／誘因": ("增強／獎勵／誘因", "增強/獎勵/誘因", "增強", "獎勵", "誘因"),
    "個人優勢／資產": ("個人優勢／資產", "個人優勢/資產", "個人優勢", "資產"),
    "專業服務": ("專業服務",),
    "物理環境": ("物理環境",),
}


def normalize_refine_aspect(name: str) -> str:
    compact_name = re.sub(r"\s+", "", str(name or ""))
    for canonical_name, aliases in REFINE_ASPECT_ALIASES.items():
        if compact_name in {re.sub(r"\s+", "", alias) for alias in aliases}:
            return canonical_name
    return compact_name


def extract_refine_aspect_sections(text: str) -> list[dict]:
    matches = list(re.finditer(r"【面向\s*[：:]\s*([^】]+)】", text or ""))
    sections = []
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        sections.append({
            "name": normalize_refine_aspect(match.group(1)),
            "start": match.start(),
            "end": end,
            "text": text[match.start():end].strip(),
        })
    return sections


def detect_refine_target_aspect(refine_prompt: str) -> str | None:
    prompt_text = str(refine_prompt or "")
    matched_aspects = []
    for canonical_name, aliases in REFINE_ASPECT_ALIASES.items():
        full_names = aliases[:2] if len(aliases) > 1 else aliases
        has_full_name = any(alias in prompt_text for alias in full_names)
        has_explicit_short_name = any(
            re.search(rf"{re.escape(alias)}\s*(?:這個)?\s*面向", prompt_text)
            or re.search(rf"面向\s*[：:]?\s*{re.escape(alias)}", prompt_text)
            for alias in aliases
        )
        if has_full_name or has_explicit_short_name:
            matched_aspects.append(canonical_name)
    return matched_aspects[0] if len(matched_aspects) == 1 else None


def replace_refine_aspect(original: str, target_aspect: str, generated_text: str) -> str | None:
    original_sections = extract_refine_aspect_sections(original)
    generated_sections = extract_refine_aspect_sections(generated_text)
    original_target = next(
        (section for section in original_sections if section["name"] == target_aspect),
        None,
    )
    generated_target = next(
        (section for section in generated_sections if section["name"] == target_aspect),
        None,
    )
    if not original_target or not generated_target:
        return None
    before = original[:original_target["start"]].rstrip()
    after = original[original_target["end"]:].lstrip()
    parts = [part for part in (before, generated_target["text"], after) if part]
    return "\n\n".join(parts)


def build_refine_answer_messages(
    original: str,
    refine_prompt: str,
    intent: dict,
    service_type: str = "",
    domain: str = "",
):
    target_aspect = detect_refine_target_aspect(refine_prompt)
    expected_aspects = list(REFINE_ASPECT_ALIASES)

    if target_aspect:
        regeneration_mode = f"""
使用者已明確指定只重新生成「{target_aspect}」面向。
只輸出「【面向：{target_aspect}】」完整區段，包含 1 個短程目標與 5 條支持策略。
不要輸出其他面向；程式會將此區段替換回原始完整文件，其他六個面向維持不變。
"""
    else:
        regeneration_mode = f"""
使用者沒有明確指定單一面向，代表對原本整份生成結果不滿意。
請重新構思並輸出完整七大面向，不得只修改或示範其中一個面向。
必須依序輸出：{'、'.join(expected_aspects)}。
每個面向包含 1 個短程目標與 5 條支持策略。
原始內容只作為需求與問題參考，不要原句照抄；應依使用者要求重新生成整份結果。
"""

    return [
        (
            "system",
            f"""{SYSTEM_PROMPT}

========================================
【重新生成任務規則】
========================================
{regeneration_mode}
重新生成結果仍須符合完整 ISP/IFSP 規則、目前服務對象類型與所選領域。
""",
        ),
        (
            "user",
            f"""
【目前服務對象類型】
{service_type or '未指定'}

【使用者所選領域】
{domain or '未指定'}

【原始完整內容】
{original}

【使用者原始要求】
{refine_prompt}

【解析後的修改需求】
{json.dumps(intent, ensure_ascii=False, indent=2)}

請依重新生成任務規則輸出結果。只輸出短程目標與支持策略，不要寫前言、結論、修改摘要或說明。
""",
        ),
    ]


def finalize_refined_answer(
    original: str,
    refine_prompt: str,
    refined: str,
) -> tuple[str | None, str | None]:
    target_aspect = detect_refine_target_aspect(refine_prompt)
    expected_aspects = list(REFINE_ASPECT_ALIASES)

    if target_aspect:
        merged_result = replace_refine_aspect(original, target_aspect, refined)
        if merged_result is None:
            return None, (
                f"上一版格式不完整。請只重新輸出【面向：{target_aspect}】完整區段，"
                "必須包含短程目標與 5 條支持策略，不要輸出說明。"
            )
        return merged_result, None

    returned_aspects = {
        section["name"] for section in extract_refine_aspect_sections(refined)
    }
    missing_aspects = [
        aspect for aspect in expected_aspects if aspect not in returned_aspects
    ]
    if missing_aspects:
        return None, f"""
上一版回覆不完整，缺少：{'、'.join(missing_aspects)}。
請重新輸出完整七大面向，依序包含：{'、'.join(expected_aspects)}。
每個面向都必須包含 1 個短程目標與 5 條支持策略。不得只補缺少部分，也不得輸出說明。
"""
    return refined, None
